import{_ as s,o as a,c as i,a2 as n}from"./chunks/framework.BfI5QxtK.js";const k=JSON.parse('{"title":"Packaging and releases","description":"","frontmatter":{},"headers":[],"relativePath":"distribution.md","filePath":"distribution.md"}'),t={name:"distribution.md"};function l(r,e,o,h,p,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="packaging-and-releases" tabindex="-1">Packaging and releases <a class="header-anchor" href="#packaging-and-releases" aria-label="Permalink to &quot;Packaging and releases&quot;">​</a></h1><p>For user installation, see <a href="./installation">Install Gnoblin</a>. This page is for release maintainers.</p><h2 id="package-layout" tabindex="-1">Package layout <a class="header-anchor" href="#package-layout" aria-label="Permalink to &quot;Package layout&quot;">​</a></h2><p>Gnoblin must install alongside GNOME.</p><ul><li>RPM names: <code>gnoblin-mutter</code>, <code>gnoblin-shell</code>, <code>gnoblin-session</code>.</li><li>Debian/Ubuntu name: <code>gnoblin</code> (compositor, session and private libraries together).</li><li>Private runtime: <code>/usr/lib/gnoblin</code>.</li><li>Public files: login entry, control tool, service units and named policy files.</li><li>Private libraries must not satisfy stock GNOME dependencies.</li></ul><p>Nix uses separate store outputs. Source builds use a private prefix. Bingux owns and releases its shell package separately.</p><h2 id="package-definitions" tabindex="-1">Package definitions <a class="header-anchor" href="#package-definitions" aria-label="Permalink to &quot;Package definitions&quot;">​</a></h2><p><code>nix/native-packages.nix</code> defines the RPM and Arch adapters and their package-name mappings. Generate or verify those adapters with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .#lib.nativePackages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package-manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> write</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package-manifest</span></span></code></pre></div><p>Fedora&#39;s COPR packages use <code>gnoblin-session</code> as the entry point. Debian and Ubuntu use the <code>gnoblin</code> package from the signed <a href="./install-debian">Gnoblin APT archive</a>. There is no pacman repository.</p><h2 id="build-debian-and-ubuntu-packages" tabindex="-1">Build Debian and Ubuntu packages <a class="header-anchor" href="#build-debian-and-ubuntu-packages" aria-label="Permalink to &quot;Build Debian and Ubuntu packages&quot;">​</a></h2><p>The supported targets are Debian 13, Ubuntu 24.04 LTS and Ubuntu 26.04 LTS. Build separately in each distribution&#39;s container; do not reuse a newer distribution&#39;s binary package on an older one.</p><p>Follow the <a href="https://github.com/kierandrewett/gnoblin/blob/main/packaging/deb/README.md" target="_blank" rel="noreferrer">container build instructions</a>. The builder compiles the required newer libraries into <code>/usr/lib/gnoblin/deps</code> and produces a <code>.deb</code> with the remaining system dependencies recorded for APT. No Nix installation is required.</p><p>The package tests install stock GNOME first, then exercise Gnoblin&#39;s installed CLI and compositor in a headless session. They also check removal and verify that GNOME&#39;s binary is unchanged. A real login test remains part of release verification.</p><h2 id="prepare-fedora-source-rpms" tabindex="-1">Prepare Fedora source RPMs <a class="header-anchor" href="#prepare-fedora-source-rpms" aria-label="Permalink to &quot;Prepare Fedora source RPMs&quot;">​</a></h2><p>Use a clean release checkout and install <code>rpm-build</code> and <code>copr-cli</code>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/make-tarball.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/sources</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/make-tarball.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnome-shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/sources</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/build-srpm.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/sources</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/srpms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/build-srpm.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnome-shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/sources</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/srpms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/build-srpm.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnoblin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/sources</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/srpms</span></span></code></pre></div><p>Archives include Gnoblin&#39;s overlays and patches. They must not be replaced with unpatched upstream archives.</p><h2 id="publish-to-copr" tabindex="-1">Publish to COPR <a class="header-anchor" href="#publish-to-copr" aria-label="Permalink to &quot;Publish to COPR&quot;">​</a></h2><p>Configure a Fedora account using the <a href="https://copr.fedorainfracloud.org/api/" target="_blank" rel="noreferrer">COPR API page</a>. Keep credentials outside the repository.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/publish-copr.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OWNER/gnoblin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATH_TO_MUTTER_SRPM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATH_TO_SHELL_SRPM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATH_TO_META_SRPM</span></span></code></pre></div><p>Replace the owner and paths. The script waits for Mutter before building Shell. Do not use asynchronous submission that bypasses this dependency.</p><p>Use a currently available chroot supplying the required dependencies. After all builds succeed, test package resolution, login and removal on a clean host using <a href="./real-hardware-verification">hardware verification</a>.</p><h2 id="github-releases" tabindex="-1">GitHub releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub releases&quot;">​</a></h2><p>Gnoblin and GNOME version independently. <code>gnoblin-version.json</code> is the canonical Gnoblin <a href="https://semver.org/" target="_blank" rel="noreferrer">SemVer</a> identity; <code>gnome-versions.json</code> continues to pin the compatible GNOME train. For example, Gnoblin <code>0.1.0</code> can target GNOME <code>51.0</code> without claiming that it is GNOME version <code>0.1.0</code>.</p><p>Before release, update <code>gnoblin-version.json</code> deliberately: use a major version for incompatible Gnoblin configuration or protocol changes, a minor version for backwards-compatible features, and a patch version for compatible fixes. Then push the release commit and a signed <code>gnoblin-v&lt;semver&gt;</code> tag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnoblin-v0.1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Gnoblin 0.1.0 (GNOME 51.0)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnoblin-v0.1.0</span></span></code></pre></div><p>The release workflow builds source archives, source RPMs, Debian/Ubuntu binary packages and checksums. All three Debian/Ubuntu build and install tests must pass before assets are published. Asset names and package metadata include both versions; for example, a Debian package is versioned <code>51.0+gnoblin0.1.0-1~debian13</code>. Dependency sources accompany the binaries. Manual dispatch can repair assets for an existing SemVer tag. Historical <code>v&lt;gnome-version&gt;</code> tags predate this convention and remain historical releases.</p><p>The release workflow then publishes the same source RPMs to COPR and installs the result in a Fedora 44 container before it completes. The workflow requires the repository secret <code>COPR_CONFIG</code>, containing the publisher&#39;s <code>copr-cli</code> configuration. Configure it once before the first automated release:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> COPR_CONFIG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/copr</span></span></code></pre></div><p>Debian and Ubuntu packages are added to the signed APT archive after the GitHub release; Fedora users receive the resulting COPR update through normal <code>dnf</code> updates. Check the completed release workflow before telling users a release is available.</p><h2 id="upgrade-the-gnome-base" tabindex="-1">Upgrade the GNOME base <a class="header-anchor" href="#upgrade-the-gnome-base" aria-label="Permalink to &quot;Upgrade the GNOME base&quot;">​</a></h2><p><code>gnome-versions.json</code> pins the release train.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/gnome-versions.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 52</span></span></code></pre></div><p>Use the intended major version. The script verifies upstream tags and updates generated version fields. Then rebase patches, update submodule references and run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-gnome-version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>Patch rebasing and runtime compatibility still require review.</p><h2 id="release-checklist" tabindex="-1">Release checklist <a class="header-anchor" href="#release-checklist" aria-label="Permalink to &quot;Release checklist&quot;">​</a></h2><ol><li>Build all artifacts from the release checkout.</li><li>Verify private package paths and stock GNOME coexistence.</li><li>Publish packages and check dependency resolution.</li><li>Test login, shell startup, portal access and removal on a clean host.</li><li>Update installation commands and version notes to match published packages.</li></ol>`,39)])])}const u=s(t,[["render",l]]);export{k as __pageData,u as default};
